// Demo stand-in for "select an invoice": a synthetic, fictional EN16931
// fixture ("Unternehmen X"), embedded so this workflow is self-contained
// and runnable via `n8n execute` with no filesystem mounts. A production
// deployment replaces this node with a Form Trigger file-upload field or a
// Read/Write File From Disk node reading a real inbound invoice.
const demoInvoiceBase64 = "";

const buffer = Buffer.from(demoInvoiceBase64, "base64");
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  "invoice.xml",
  "application/xml"
);

return [
  {
    json: {
      demoNote: "Synthetic fictional EN16931 invoice (Unternehmen X) -- no real invoice or organization data.",
    },
    binary: {
      invoiceFile: binaryData,
    },
  },
];

const capabilities = $input.first().json;
const facturX = capabilities.structuredFormats["factur-x"];
// PR #6 replaced the old flat facturX.xsdVersion/legacyBaseline fields with
// a per-level xsdBaselines map (each recognized level is genuinely on its
// own XSD baseline now) -- reading the old fields silently produced
// "XSD undefined" against the merged API. Read the EN16931 baseline
// specifically, since that's the only processable level.
const en16931Baseline = facturX.xsdBaselines.en16931;
const schematron = capabilities.schematron;

const versionNote = en16931Baseline.legacyBaseline
  ? `Using LEGACY validator baseline: XSD ${en16931Baseline.version} ` +
    `(processable profiles: ${facturX.processableLevels.join(", ")}). ` +
    `Upgrade is tracked separately and does not block this demo.`
  : `Using validator baseline: Factur-X ${en16931Baseline.version} EN16931 ` +
    `(Schematron ${schematron.status}, artifact ${schematron.artifactVersion}, ` +
    `engine ${schematron.engine}).`;

// HTTP Request and Code nodes don't automatically carry binary data
// forward from earlier nodes -- reach back to where the demo invoice was
// attached so the next node (03.1 Run DigiTax controls) still has it.
const invoiceBinary = $('01.2 Load demo fixture').item.binary;

return [
  {
    json: {
      versionNote,
      xsdVersion: en16931Baseline.version,
      legacyBaseline: en16931Baseline.legacyBaseline,
      processableLevels: facturX.processableLevels,
      schematronStatus: schematron.status,
    },
    binary: invoiceBinary,
  },
];

// Bounded retry on "02.1 Read API capabilities" is already exhausted by the time
// this node runs (onError: continueErrorOutput on that node).
const ctx = $('01.3 Build run context').item.json;
const raw = $input.first().json;
const explanation =
  (raw && raw.error && (raw.error.message || raw.error)) ||
  (raw && raw.message) ||
  "The capabilities service did not respond after the bounded retry.";
const gateDecisionAt = new Date().toISOString();
const n8nErrorCode = "CAPABILITIES_SERVICE_UNAVAILABLE";

const summaryLines = [
  "Technical failure while contacting the Factur-X Phase 1 API.",
  "",
  "Failed step: 02.1 Read API capabilities",
  `Error code: ${n8nErrorCode}`,
  `Correlation ID: ${ctx.correlationId}`,
  `Explanation: ${explanation}`,
  "",
  "OVERALL STATUS: nicht_pruefbar (routing: technical_review)",
  "",
  "This is a Phase 1 technical-failure finding for human review only -- it",
  "is not an approval, rejection, booking, payment, or supplier communication.",
];

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome: "PRE_FLIGHT_REJECTED",
    report: null,
    httpErrorCode: null,
    n8nErrorCode,
    explanation,
    phase1AttemptStartedAt: null,
    gateDecisionAt,
    phase1Status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "02.1 Read API capabilities",
    failedControlCount: null,
    failedControls: [],
    reportId: null,
    runId: null,
    sourceSha256: null,
    reviewSummary: summaryLines.join("\n"),
  },
}];

// Bounded retry on "03.1 Run DigiTax controls" is already exhausted by the
// time this node runs (onError: continueErrorOutput on that node).
const ctx = $('01.3 Build run context').item.json;
const attemptStart = $('02.9 Mark phase1 attempt start').item.json.phase1AttemptStartedAt;
const raw = $input.first().json;
const errObj = (raw && raw.error) || {};
const errMessage = (errObj.message || errObj || (raw && raw.message) || "").toString();
const errCode = (errObj.code || "").toString();
const isTimeout = /ETIMEDOUT|ECONNABORTED/i.test(errCode) || /timeout/i.test(errMessage);
const outcome = isTimeout ? "TIMEOUT" : "TRANSPORT_FAILURE";
const n8nErrorCode = isTimeout ? "INVOICE_PROCESSING_SERVICE_TIMEOUT" : "INVOICE_PROCESSING_SERVICE_UNAVAILABLE";
const explanation = errMessage || "The invoice processing service did not respond after the bounded retry.";

const summaryLines = [
  "Technical failure while contacting the Factur-X Phase 1 API.",
  "",
  "Failed step: 03.1 Run DigiTax controls",
  `Error code: ${n8nErrorCode}`,
  `Correlation ID: ${ctx.correlationId}`,
  `Explanation: ${explanation}`,
  "",
  "OVERALL STATUS: nicht_pruefbar (routing: technical_review)",
  "",
  "This is a Phase 1 technical-failure finding for human review only -- it",
  "is not an approval, rejection, booking, payment, or supplier communication.",
];

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome,
    report: null,
    httpErrorCode: null,
    n8nErrorCode,
    explanation,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    phase1Status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "03.1 Run DigiTax controls",
    failedControlCount: null,
    failedControls: [],
    reportId: null,
    runId: null,
    sourceSha256: null,
    reviewSummary: summaryLines.join("\n"),
  },
}];

const ctx = $('01.3 Build run context').item.json;
const attemptStart = $('02.9 Mark phase1 attempt start').item.json.phase1AttemptStartedAt;
const response = $input.first().json;
const invoice = response.canonicalInvoice.invoice;
const document = response.canonicalInvoice.document;
const report = response.phase1ControlReport;

const failedControls = report.controls.filter(
  (c) => !["passed", "not_applicable", "not_run"].includes(c.outcome)
);

const summaryLines = [
  `Invoice ${invoice.invoiceNumber || "(missing)"} dated ${invoice.issueDate || "(missing)"}`,
  `Supplier: ${invoice.supplier.name || "(missing)"} -> Buyer: ${invoice.buyer.name || "(missing)"}`,
  `Totals: net ${invoice.totals.lineNet}, tax ${invoice.totals.taxAmount}, gross ${invoice.totals.grossAmount}, payable ${invoice.totals.payableAmount} ${invoice.currency || ""}`,
  `Detected format/profile: ${document.detectedFormat} / ${document.profile || "(none)"}`,
  `Catalog ${report.catalogVersion} / control profile ${report.controlProfileId} v${report.controlProfileVersion}`,
  ``,
  `OVERALL STATUS: ${report.status} (routing: ${report.routing})`,
  ``,
  failedControls.length === 0
    ? "All applicable controls passed."
    : `${failedControls.length} control(s) require human review:`,
  ...failedControls.map(
    (c) =>
      `  - ${c.controlId} [${c.outcome}/${c.severity}] ${c.reasonCodes.join(", ")}: ` +
      `${c.message || "(no message)"}` +
      (c.details ? ` | details: ${JSON.stringify(c.details)}` : "") +
      ` | evidence: ${c.evidenceRefs.join(", ")}`
  ),
  ``,
  `This is a Phase 1 finding for human review only -- it is not an approval,`,
  `rejection, booking, payment, or supplier communication.`,
];

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome: "REPORT",
    report,
    httpErrorCode: null,
    n8nErrorCode: null,
    explanation: null,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    phase1Status: report.status,
    routing: report.routing,
    failedStep: null,
    failedControlCount: failedControls.length,
    failedControls,
    reportId: report.reportId,
    runId: report.runId,
    sourceSha256: report.sourceSha256,
    reviewSummary: summaryLines.join("\n"),
  },
}];

// No weak fallback: a missing crypto.randomUUID must fail visibly rather
// than mint a low-entropy identity for evidence.
// The n8n JS Task Runner sandbox does not expose a bare `crypto` global
// (confirmed against the real pinned n8nio/n8n:2.33.7 image) -- the built-in
// must be required explicitly, and require() itself is denied unless
// allow-listed (NODE_FUNCTION_ALLOW_BUILTIN=crypto, set on the n8n
// container -- see docker-compose.phase1-upload-demo.yml). No weak
// fallback: an unavailable/disallowed crypto module must fail visibly
// rather than mint a low-entropy identity for evidence.
let randomUUID;
try {
  randomUUID = require("crypto").randomUUID;
} catch (e) {
  randomUUID = undefined;
}
if (typeof randomUUID !== "function") {
  throw new Error(
    "SECURE_UUID_UNAVAILABLE: refusing to mint a weak identifier for correlationId/processInstanceId without crypto.randomUUID() (require(\"crypto\") must be allow-listed via NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance)."
  );
}
const correlationId = randomUUID();
const processInstanceId = randomUUID();
const item = $input.first();

return [{
  json: { ...item.json, correlationId, processInstanceId, receivedAt: new Date().toISOString() },
  binary: item.binary,
}];

// Reconciles the shared subworkflow's minimal { activityExecution } return
// with the branch's own envelope (reviewSummary/phase1Status/routing/...)
// that this workflow's downstream nodes/tests still expect under their
// original field names.
function tryGetBranchEnvelope(nodeName) {
  try {
    const item = $(nodeName).item;
    return item ? item.json : undefined;
  } catch (e) {
    return undefined;
  }
}

const BRANCH_NODE_NAMES = [
  "02.3 Handle capabilities failure",
  "03.2 Handle controls-call failure",
  "04.1 Build control report",
];

let envelope;
for (const name of BRANCH_NODE_NAMES) {
  const candidate = tryGetBranchEnvelope(name);
  if (candidate !== undefined) {
    envelope = candidate;
    break;
  }
}
if (!envelope) {
  throw new Error("ACTIVITY_EXECUTION_MERGE_NO_BRANCH_ENVELOPE: could not locate the originating branch node's output.");
}

const { activityExecution } = $input.first().json;

return [{
  json: {
    reviewSummary: envelope.reviewSummary,
    status: envelope.phase1Status,
    routing: envelope.routing,
    failedStep: envelope.failedStep,
    errorCode: envelope.httpErrorCode || envelope.n8nErrorCode,
    correlationId: envelope.correlationId,
    processInstanceId: envelope.processInstanceId,
    explanation: envelope.explanation,
    failedControlCount: envelope.failedControlCount,
    failedControls: envelope.failedControls,
    reportId: envelope.reportId,
    runId: envelope.runId,
    sourceSha256: envelope.sourceSha256,
    activityExecution,
  },
}];
